int atMost(const vector<int>& a, int k){
  if(k < 0) return 0;
  int l = 0, c = 0, cnt = 0;
  for(int r = 0; r < (int)a.size(); r++){
    cnt += a[r] & 1;
    while(cnt > k) cnt -= a[l++] & 1;
    c += r - l + 1;
  }
  return c;
}
// exactly k = atMost(k) - atMost(k - 1)

